  'props.name': 'Nimi',
  'props.nameHint': 'Üks failinimi, mitte kunagi tee: kõik, mis kaustu välja kirjutab, lõigatakse ühe nimeni. Lõpetatud allalaadimine nimetatakse ümber ka kettal, et loend ja kaust ei saaks üksteisele vastu rääkida. Käimasolev hoiab faili, mis tema taustamootoril avatud on, ja võtab uue nime lõpetades. Alustamata võtab selle kohe. Nimi kuulub ühele failile, seega pakutakse seda kasti ainult ühe rea puhul.',
