  'settings.access.relay.title': 'Projekti relee',
  'settings.access.relay.body': 'Relee on vahendaja, tänu millele on kõik sinu instantsid kättesaadavad väljaspool koduvõrku, seega kõikjalt. Selle pakub projekt tasuta.',
  'settings.access.relay.use': 'Kasuta projekti releed',
  'settings.access.relay.leadProject': 'Töötab ilma seadistamata. Kõik, mida su eksemplarid teineteisele ütlevad, on krüptitud, ja võti on ainult sinul.',
  'settings.access.relay.seesButton': 'Mida ta näeb?',
  'settings.access.relay.seesTip': 'Releele nähtamatu: sinu lingid, allalaadimised, failid ja juurdepääsutoken.\n\nReleele nähtav: sinu instantside IP-aadressid ja millal nad midagi saadavad.\n\nSeda ei saa krüpteerimisega ära peita. Kui see häirib, kasuta oma releed.',
  'settings.access.relay.seesAddress': 'Projekti relee töötab aadressil {address}.',
  'settings.access.relay.none': 'Releed pole',
  'settings.access.relay.noneHint': 'Ükski relee pole aktiivne. Samas võrgus, see tähendab kodus, leiavad instantsid endiselt ise teineteist. Eri võrkude vahel nad teineteist ei taba, seega kaugjuurdepääsu ei ole.',
  'settings.access.relay.own': 'Oma relee',
  'settings.access.relay.project': 'Projekti relee',
