  'settings.access.ownRelay.title': 'Sinu oma relee',
  'settings.access.ownRelay.body': 'Käita oma releed projekti oma asemel.',
  'settings.access.ownRelay.use': 'Kasuta minu oma releed',
  'settings.access.ownRelay.lead': 'Kaks teed: see eksemplar võtab relee, või sisestad aadressi.',
  'settings.access.ownRelay.serveLabel': 'Kasuta seda instantsi releena',
  'settings.access.ownRelay.serveHint': 'Töötab ainult siis, kui see instants on väljastpoolt kättesaadav, näiteks Nginx Proxy Manageri ja oma domeeni kaudu.',
  'settings.access.ownRelay.serveClients': '{count} praegu ühendatud.',
  'settings.access.ownRelay.addressLabel': 'Aadress',
  'settings.access.ownRelay.addressPlaceholder': 'nt https://relay.minudomeen.ee',
  'settings.access.ownRelay.save': 'Salvesta',
  'settings.access.ownRelay.everyInstance': 'See aadress kehtib ainult sellele eksemplarile. Sisesta see igasse eksemplari.',
  'settings.access.ownRelay.containerLabel': 'Omaette konteinerina',
  'settings.access.ownRelay.containerHint': 'Kui ükski sinu eksemplar pole väljastpoolt kättesaadav, peab relee asuma mujal, sinu serveris või väikeses VPS-is. Paigalda konteiner Unraid Community Applicationsist või allpool oleva käsuga.\n\nKonteiner ei vaja seadistamist: käivita see, sisesta selle aadress ülal, valmis. See ei salvesta midagi, seega pole ka midagi varundada.',
  'settings.access.tokens.title': 'API tokenid',
  'settings.access.tokens.intro':
    'Nimega mandaadid skriptile, brauserilaiendusele või telefonile. Igaühe saab omaette tühistada, ilma jagatud parooli muutmata, mida kasutab iga teine klient.',
