  'settings.access.identity.title': 'Selle eksemplari identiteet',
  'settings.access.identity.nameLabel': 'Nimi',
  'settings.access.identity.namePlaceholder': 'nt Kodune server',
  'settings.access.identity.nameHint': 'Pakutakse sidumisel ja allolevas QR-koodis esimesena, selle nime asemel, mille operatsioonisüsteem või konteineri käituskeskkond sellele masinale juhtub andma. Valikuline: jäta tühjaks, et seda nime edasi kasutada.',
  'settings.access.identity.domainsLabel': 'Teadaolevad domeenid',
  'settings.access.identity.domainsHint': 'Iga domeen jäetakse automaatselt meelde, kui selle kaudu saabub esimene päring, ja see jääb siia loetletuks ka siis, kui hilisemad päringud tulevad hoopis LAN-i IP kaudu. Lisa domeen käsitsi, kui see on juba seadistatud, aga selle kaudu pole veel ühtegi päringut tulnud. Üks täielik aadress rea kohta, nt https://kl.example.com.',
  'settings.access.cardTitle': 'Ühenda eksemplarid ja kaugjuurdepääs',
  'settings.access.phrase.body': 'Üks fraas ühendab kõik sinu KnightLoaderid. Loo see siin ja kleebi see siis oma teistesse eksemplaridesse. Sul pole vaja kontot ega sisselogimist ja seadistada pole midagi.',
  'settings.access.phrase.noPasswordWarning': 'Sellel eksemplaril pole parooli. Fraas avab iga eksemplari, mille sellega ühendad, nii et kes seda siin lugeda saab, jõuab kõigini, mitte ainult selleni. Parem sea kõigepealt ülal parool.',
  'settings.access.phrase.activate': 'Loo fraas',
  'settings.access.phrase.howStep1': 'Vajuta sellel eksemplaril „{button}“. Ilmub kaksteist sõna.',
  'settings.access.phrase.howStep2': 'Ava KnightLoader teises masinas, tule samale lehele, vajuta „{button}“ ja sisesta kaksteist sõna.',
  'settings.access.phrase.howStep3': 'Valmis! Kumbki instants ilmub nüüd teise juures „Instantside“ alla ja sa juhid kumbagi kummastki. Sisselülitatud releega on su instantsid kättesaadavad ka väljastpoolt su võrku.',
  'settings.access.phrase.howWhat': 'Sõnad on saladus, mitte aadress. Iga instants arvutab neist kaks võtit: ühe teiste leidmiseks, teise krüptimiseks.\n\nÜksteise leidmiseks helistab iga instants ise samasse kohtumispaika internetis. Kes näitab sama võtit, see ühendatakse. Seepärast ei pea ükski sinu instants olema väljastpoolt kättesaadav.\n\nKohtumispaik ei saa kaasa lugeda. Sinu sõnu ta kunagi ei näe ja kõik, mis sealt läbi käib, on teise võtmega krüptitud.',
  'settings.access.phrase.statusDisconnected': 'Pole ühendatud',
  'settings.access.phrase.statusHintProject': 'Ühendatud projekti releega. Kaugjuurdepääs on seadistatud.',
  'settings.access.phrase.statusHintOwn': 'Ühendatud oma releega. Kaugjuurdepääs on seadistatud.',
  'settings.access.phrase.statusHintOff': 'Ükski relee pole aktiivne. Sinu instantsid on kättesaadavad ainult kohtvõrgus.',
  'settings.access.phrase.statusHintLost': 'Releega puudub ühendus. KnightLoader üritab edasi. Seni leiavad instantsid teineteist ainult kohtvõrgus.',
  'settings.access.phrase.statusConnected': 'Ühendatud',
