  'settings.resolvers.intro': 'yt-dlp taustaprogrammi seaded; see toob meedia- ja voogedastussaite, mida yt-dlp ise toetab. Milline teenus konkreetset linki üldse käsitleb (yt-dlp, debrid-konto või headless JD sidecar), otsustab lehe Kontod suunamisjärjekord. See leht määrab, mida yt-dlp teeb, kui link on talle suunatud.',
