  'settings.torrents.uploadLimitUnit': 'KiB/s',
  'settings.torrents.portTitle': 'Port ja suunamine',
  'settings.torrents.port': 'Port',
  'settings.torrents.portHint': 'Port, mida see eksemplar parve ühenduste jaoks kuulab. 0 laseb torrendimootoril endal valida.',
  'settings.torrents.portMapHint': 'Palub ruuteril suunata ülaltoodud pordi UPnP kaudu sellesse masinasse, et teise ruuteri taga olevad peerid saaksid seda siiski tabada. Mitte iga ruuter ei toeta seda ja mõni võtab päringu vastu, ilma et see tegelikult töötaks.',
  'settings.torrents.portMapButton': 'Proovi UPnP suunamist',
  'settings.torrents.portMapping': 'Küsitakse ruuterilt…',
  'settings.torrents.portMapNeedsPort': 'Määra enne suunamist ülal port. Väärtusega 0 pole ruuteril kuhu suunata.',
  'settings.torrents.portMapConfirmed': 'Kinnitatud: port {port} on suunatud ja kontrollitud kättesaadavana.',
  'settings.torrents.portMapUnconfirmed': 'Ruuter võttis päringu vastu, aga ei õnnestunud kinnitada, et suunamine töötab. Mõni ruuter võtab päringu vaikselt vastu, ilma seda rakendamata. Proovi ühenduvuse kontrolli väljastpoolt võrku.',
  'settings.torrents.portMapFailed': 'Pordi suunamine ebaõnnestus: {error}',
