  'settings.torrents.networkTitle': 'Peeride avastamine',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Leiab peere ilma trackerita, kasutades teisi BitTorrenti kliente hajutatud loendina.',
  'settings.torrents.pex': 'Peeride vahetus (PEX)',
  'settings.torrents.pexHint': 'Vahetab teadaolevaid peere juba ühendatutega, et vähemate peeridega parv leitaks kiiremini.',
  'settings.torrents.privateNote': 'Privaatne torrent lülitab mõlemad automaatselt välja kohe, kui selle metaandmed on teada, olenemata siinsest seadest: üles laaditud .torrent-faili puhul kohe, magnetlingi puhul niipea, kui selle enda metaandmed parvest kohale jõuavad. Enamik privaatseid trackereid blokeerib kontod, mis kasutavad kumbagi.',
  'container.noJD': 'see on krüptitud ja ainult JDownloaderi taustsüsteem suudab selle avada. Ühtegi pole seadistatud: sea KL_JD JDownloaderile, milleni see eksemplar ulatub, ja käivita uuesti.',
  'container.jdOff': 'see on krüptitud ja ainult JDownloaderi taustsüsteem suudab selle avada. „JDownloaderi taustsüsteem“ on lehel Moodulid välja lülitatud.',
  'torrent.staging': 'Lisatakse…',
  'torrent.staged': '{file} lisati kogujasse.',
  'torrent.stagedIn': '{file} lisati kogujasse „{pkg}“.',
  'torrent.duplicate': '{file} on juba loendis.',
  'torrent.onlyOne': 'korraga saab läbi vaadata ainult ühe .torrent-faili',
  'torrent.tree.summary': 'Valitud {n} / {total} faili ({size})',
  'torrent.tree.private': 'Privaatne tracker',
  'torrent.tree.selectAll': 'Vali kõik',
  'torrent.tree.selectNone': 'Tühista valik',
  'torrent.tree.cancel': 'Loobu',
  'torrent.tree.add': 'Lisa kogujasse',

  'settings.torrents.engineLimits': 'Levitamise sihtsuhe ja levitamise sihtkestus kehtivad igale torrentile, mille see mootor käivitab. Port kehtib ainult esimesele torrentile, mis käivitub pärast selle eksemplari viimast taaskäivitust, sest mootor ehitab oma torrendikliendi ühe korra ega ehita seda kunagi uuesti. Hilisem pordimuudatus salvestatakse siiski õigesti ja jõustub pärast järgmist taaskäivitust. Üleslaadimispiirangut seni ainult salvestatakse ja kontrollitakse; mootor ei suuda seda veel käimasolevale allalaadimisele rakendada. Tavalise torrenti puhul ei mõju veel ka allpool olevad DHT ja PEX: selle eksemplari enda vaikeväärtus ei jõua käimasoleva allalaadimiseni, seega levitab torrent mõlemaga sisse lülitatult, olenemata sellest, mis siin on seatud. Privaatne torrent on teine juhtum, seda selgitab allpool „Peeride avastamine“ juures olev (i). Allpool olev suunamisnupp töötab sellest hoolimata: see palub ruuteril suunata ülal sisestatud pordinumbri, olenemata sellest, kas mõni torrent seda juba kuulab.',
  'onboarding.step': 'Samm {n} / {total}',
  'onboarding.skip': 'Jäta vahele',
  'onboarding.back': 'Tagasi',
  'onboarding.next': 'Edasi',
  'onboarding.finish': 'Valmis',
  'onboarding.welcome.title': 'Tere tulemast KnightLoaderisse',
  'onboarding.welcome.body': 'KnightLoader on ise majutatav allalaadimishaldur. Kleebi või lohista link ja selle toob sobiv taustaprogramm: sisseehitatud mootor tavaliste faililinkide jaoks, yt-dlp meedialehtede jaoks, debrid-teenus hosterite jaoks, mille eest juba maksad, või headless JDownloader kõige muu jaoks. See lühike tutvustus käsitleb ühte seadet, mida tasub enne alustamist kontrollida.',
  'onboarding.welcome.langLabel': 'Liidese keel',
  'onboarding.folder.title': 'Kuhu peaksid failid jõudma?',
  'onboarding.folder.body': 'See on kaust, kuhu valmis allalaadimised kirjutatakse. Sisesta tee või sirvi serverit, et see leida. Saad seda igal ajal uuesti muuta seadete lehel Üldine.',
  'onboarding.accounts.title': 'Premium-hostid, millal iganes soovid',
  'onboarding.accounts.body': 'Järjekord töötab täiesti ilma kontota. Kui tahad täiskiirust hosteris või debrid-teenuses, mille eest juba maksad, lisa selle sisselogimine jaotises Kontod. Midagi sellest ei pea praegu seadistama.',
  'onboarding.accounts.link': 'Ava Kontod',
  'onboarding.finished.title': 'Kõik on valmis',
  'onboarding.finished.body': 'Sellega tutvustus lõpeb. Seadete all olev abilehekülg sisaldab täielikku ülevaadet kõigest muust, mida see versioon teeb, ning enamik juhtelemente kannab oma selgitust (i)-ikooni taga.',

