  'settings.feeds.lastPolledHint': 'Millal seda tellimust viimati vaadati, olenemata sellest, kas vaatamine õnnestus. Serveri taaskäivitusel läheb see teadmine kaotsi, see aga, mille tellimus on juba sisse toonud, mitte. Voog, mida sa oled kuid jälginud, seisab seetõttu paar sekundit pärast taaskäivitust kontrollimatuna.',
  'settings.feeds.pollFailed': 'Viimane kontroll ebaõnnestus',
