  'settings.feeds.seededHint': 'Uue tellimuse esimene tõmme paneb kirja kõik, mida voog sel hetkel kannab, ja ei võta sellest midagi sisse, et sulle ei kukuks korraga sisse avaldaja terve arhiiv. Sisse tuleb alles see, mis pärast seda ilmub.',
  'settings.feeds.remembered': '{n} kirjet meeles',
  'settings.feeds.rememberedHint': 'Kui palju kirjeid see tellimus ära tunneb, et neid ei võetaks teist korda sisse, kuni voog neid veel välja annab. Kõige rohkem 500 tellimuse kohta. Kõigepealt kukuvad välja vanimad, ja kirje, mis on veel voos, ei ole kunagi nende seas.',
  'settings.feeds.test': 'Testi',
  'settings.feeds.testBusy': 'Tõmban…',
