  'settings.headerProfiles.title': 'Päiseprofiilid',
  'settings.headerProfiles.hint': 'Mõni sait annab faili välja ainult sisse logitud brauserile või ainult siis, kui tullakse mõnelt tema enda lehelt. Profiil hoiab päised täpselt ühe saidi jaoks, krüptitult samamoodi nagu sinu kontovõtmed, ja KnightLoader saadab need kaasa iga allalaadimisega sellelt saidilt.',
  'settings.headerProfiles.empty': 'Päiseprofiile veel ei ole.',
  'settings.headerProfiles.emptyHint': 'Üks tasub teha kohe, kui mõni allalaadimine töötab ainult seni, kuni sa oled brauseris sisse logitud.',
