  'settings.headerProfiles.namePlaceholder': 'nt forum',
  'settings.headerProfiles.origin': 'Sait',
  'settings.headerProfiles.originHint': 'Kleebi siia selle lehe aadress, kust sa päised kopeerisid. Teine port ja http https-i asemel loevad teiseks saidiks ja vajavad oma profiili. Alamdomeen ei ole peadomeeni profiiliga kaetud.',
  'settings.headerProfiles.headers': 'Päised',
