  'settings.headerProfiles.deleteConfirm': 'Kas kustutada profiil {id}? Selles olevad päised on siis kadunud ja allalaadimised saidilt {origin} lähevad jälle ilma nendeta.',
  'settings.rules.action.category': 'Kategooria',
  'settings.rules.action.categoryHint': 'Paneb sobivad lingid ühte sahtlisse loendist Kategooriad, mis on sellel lehel allpool, ja see sahtel toob kaasa oma kausta, oma koha järjekorras, oma lahtipakkimise lüliti ja oma reegli juba olemasoleva faili jaoks. Puutumata jäetuna ei ütle ükski reegel selle kohta midagi ja link jääb sorteerimata. Kui see reegel nimetab lisaks allalaadimiste kausta, võidab see kaust, ja sahtel annab kõik ülejäänu. Kustutatud sahtli nimetamine lükatakse salvestamisel tagasi, sest reegel, mis osutab sahtlile, mida ei ole, ei tee iga sobiva lingi juures üldse mitte midagi, ilma ühegi teateta.',
  'settings.rules.action.categoryNone': 'Kategooriaid veel ei ole. Tee kõigepealt sellel lehel allpool jaotises Kategooriad üks, muidu paneks see reegel lingid sahtlisse, mida ei ole.',
