  'detail.stalledSince': 'Seisab alates',
  'detail.retries': 'Senised kordused',
  'detail.retriesHint': 'Mitu korda seda allalaadimist on pärast tõrget uuesti proovitud. Niipea kui allalaadimine valmis saab, pannakse loendur nulli, seega näitab valmis rida nulli ka siis, kui katseid oli neli. Mitu katset on veel jäänud, siin ei ole: lagi sõltub põhjusest ja hosterist, ja see leht ei suuda seda välja arvutada.',
  'detail.stallRestarts': 'Taaskäivitused pärast paigalseisu',
  'detail.stallRestartsHint': 'Mitu korda paigalseisu valve on selle allalaadimise ise uuesti käivitanud. Pannakse nulli, kui allalaadimine valmis saab, täpselt nagu ülalolev loendur.',
  'detail.failure': 'Mis läks valesti',
  'detail.cause': 'Põhjus',
  'detail.message': 'Mida taustsüsteem ütles',
  'detail.messageHint': 'Lause sellelt, kes seda tuua üritas, sõna-sõnalt ja tõlkimata. See on praegune tõrge ja ei midagi muud: taaskäivitus kustutab ta ära, ja varasemaid ei hoita kusagil alles.',
  'detail.heldBack': 'Kinni hoiab',
  'detail.doing': 'Teeb praegu',
  'detail.filtered': 'Lingifilter peab kinni',
  'detail.gaveUp': 'Rohkem ei proovita',
  'detail.gaveUpHint': 'Siin on meelega lõpp, mitte katsete otsasaamise pärast: captcha, täis ketas või reegel, mis ütleb selle hosteri kohta „mitte kunagi“. Korduste arvu tõstmine ei muuda siin midagi. Märget ennast andmebaasi ei kirjutata, seega on ta pärast taaskäivitust kadunud, kuigi põhjus, mille pärast ta tekkis, jääb alles.',
  'detail.rules': 'Reeglid, mis sellele kuju andsid',
  'detail.rulesHint': 'Reeglid, mis lingi ootelepanekul sellele peale läksid, samas järjekorras, nagu nad käivitusid. Nad on ülesandes kirjas nime järgi: vahepeal ümber nimetatud reeglit enam ei leita, ja reegel, millel nime kunagi ei olnud, on kirjas selle kohaga, mis tal tookord oli. Klõps avab ta reegliredaktoris.',
  'detail.openRule': 'Ava reegliredaktoris',
  'detail.noRules': 'Ükski reegel ei puutunud seda linki.',
  'detail.player': 'Esita',
  'detail.play': 'Esita siin',
  'detail.playHint': 'Esitab faili otse sellest eksemplarist, ilma seda teist korda alla laadimata. Enne kui sa esitamise nupule vajutad, ei tooda midagi, ja fail jääb sinna, kus ta on.',
  'detail.playPartial': 'See allalaadimine ei ole valmis. Esitada saab ainult seda osa, mis on juba kettal, sellest edasi hüpata ei saa, ja mõni fail ei esita üldse midagi, enne kui viimane bait kohal on.',
  'detail.playUnsupported': 'See brauser ei oska seda faili esitada. Ava või salvesta ta selle asemel paremklõpsumenüüst.',
  'detail.playRemote': 'Esitada saab ainult selles eksemplaris olevaid faile. Teine eksemplar annab oma failid ühe tükina ja ilma hüppamiseta edasi, ja sellega mängija toime ei tule.',
  'detail.playNotLocal': 'Selle allalaadimise tõi JDownloader, seega asub fail selle protsessi kettal, mitte siinsel.',
  'detail.playNoFile': 'Kettal ei ole veel midagi, mida esitada.',
  'detail.playRefused': 'Server ei anna seda faili välja: {reason}',
  'detail.playFailed': 'Esitamine katkes: {reason}',
  'detail.playClose': 'Sulge mängija',

  'settings.rules.notFound': 'Ühtki reeglit nimega „{name}“ siin ei ole. Ta on ümber nimetatud või kustutatud pärast seda, kui lisati link, mis teda nimetab.',

  'notifications.title': 'Teavitused',
  'notifications.titleHint': 'Otsusta iga sündmuse kohta, kas ta ilmub mullina rakenduses, sinu operatsioonisüsteemi teavitusena või üldse mitte. Süsteemi teavitus jõuab sinuni ainult seni, kuni mõni KnightLoaderi vahekaart on lahti, ja allpool olev vaikne režiim kehtib lisaks.',
  'notifications.channel.app': 'Rakenduses',
  'notifications.channel.system': 'Süsteemi teavitus',
  'notifications.channel.silent': 'Ära näita midagi',
  'notifications.event.downloadDone': 'Allalaadimine valmis',
  'notifications.event.downloadDoneHint': 'Iga allalaadimine, mis lõpuni jõuab, annab endast märku. Kahesaja faili puhul järjekorras on see kakssada teavitust, mõtle seega hoolega järele, enne kui saadad nad süsteemi.',
  'notifications.event.downloadFailed': 'Allalaadimine ebaõnnestus',
  'notifications.event.downloadFailedHint': 'Allalaadimine, mis alla andis. Vaikne režiim ei peida seda kunagi.',
  'notifications.event.extractionDone': 'Lahtipakkimine valmis',
  'notifications.event.extractionDoneHint': 'Arhiiv, mis sai lahti pakitud. Seda ei ole seni kusagil teatatud, seepärast on ta alguses valikul „Ära näita midagi“.',
  'notifications.event.extractionFailed': 'Lahtipakkimine ebaõnnestus',
  'notifications.event.extractionFailedHint': 'Arhiiv, mis jäi pooleli. Tavaliselt on puudu parool, ja failid jäävad seisma, kuni sa sellega tegeled.',
  'notifications.event.captchaWaiting': 'Captcha ootab',
  'notifications.event.captchaWaitingHint': 'Captcha aken avaneb selles vahekaardis nii või teisiti. Alguses on ta valikul „Ära näita midagi“, sest see aken ongi juba teade, kuni sa sinna vaatad. Pane ta süsteemi teavituse peale, siis jõuab captcha sinuni ka taustal olevas vahekaardis, enne kui hoster seansi minema viskab.',
  'notifications.event.captchaFailed': 'Captcha ebaõnnestus',
  'notifications.event.captchaFailedHint': 'Keegi ei vastanud õigel ajal või vastus ei jõudnud kohale. Allalaadimine selle taga jääb seisma.',
  'notifications.event.captchaResolved': 'Captcha lahendati mujal',
  'notifications.event.captchaResolvedHint': 'Keegi teises brauseris või automaatne lahendaja vastas sellele, ja aken sulgus ise.',
  'notifications.systemUnavailable': 'Süsteemi teavitusi siin ei ole: sinu brauser pakub neid ainult üle HTTPS-i või localhostis. Kõik sellel kaardil olev ilmub sellegipoolest rakenduses.',
  'notifications.systemBlocked': 'Sinu brauser blokeerib selle aadressi teavitused. Read, mis on valikul „Süsteemi teavitus“, ilmuvad selle asemel rakenduses, kuni sa need brauseri saidiseadetes jälle lubad.',
  'notifications.systemNotGranted': 'Brauser ei andnud luba, seega jääb see sündmus rakendusse. Vali uuesti „Süsteemi teavitus“, et veel kord küsida.',
  'notifications.test': 'Saada test',
  'notifications.testBody': 'Selline näeb KnightLoaderi teavitus välja.',
