  'views.label': 'Salvestatud vaated',
  'views.save': 'Salvesta see vaade',
  'views.saveHint': 'Vaade on otsing ja filtrid, mis sul praegu seatud on, hoitud nime all, mille sa ise valid. Veerud ja järjestus siia ei kuulu, need jäetakse eraldi meelde.',
