  'views.deleteBody': 'Vaade on ainult nimi ühele otsingule ja mõnele filtrile. Kustutamine ei muuda loendis midagi ega eemalda ühtki linki.',
  'views.deleteConfirm': 'Kustuta vaade',
  'views.clearAll': 'Tühjenda otsing ja kõik filtrid',
  'views.clearAllHint': 'Otsing ja filtrid jäävad seatuks, kui sa lehelt lahkud ja tagasi tuled, nii et sa näed jälle seda loendit, mille juurest lahkusid. Sellega saad terve loendi tagasi. Salvestatud vaateid see ei puuduta.',

  'disk.title': 'Sihtkaustad',
  'disk.hint': 'Vaba ja kasutatud ruum igas kaustas, kuhu allalaadimine võib jõuda, ja kui palju järjekord peab veel igasse neist kirjutama. Arvud tulevad samast päringust, mille vastu kontrollitakse kettapiiranguid, ja on kõige rohkem paar sekundit vanad. Vaba ja kasutatud ei anna alati kokku andmekandja suurust: failisüsteem hoiab osa süsteemi jaoks tagavaraks, ja kasutajapõhine kvoot võib jätta sellele eksemplarile vähem, kui andmekandjal tegelikult on. Kaks kausta samal kettal näitavad kumbki seda ketast, seega ära liida ridu kunagi kokku.',
  'disk.free': 'Vaba',
  'disk.used': 'Kasutusel',
  'disk.size': 'Andmekandja suurus',
  'disk.queued': 'Veel kirjutada',
  'disk.queuedHint': 'Mida veel võlgu olevad allalaadimised sellesse kausta juurde kirjutaksid: suurus, mille hoster nimetas, miinus see, mis on juba kohale jõudnud. Allalaadimine, mille suurust hoster ei ütle, loeb siin nulliks, seega on see alampiir ja mitte kunagi lubadus, ja just seepärast võib terve rea allalaadimiste kõrval seista null baiti. Väljalülitatud allalaadimised jäävad välja, sama reegel kehtib ka loendi all olevatele kokkuvõtetele. Juba töötaval allalaadimisel on ruum kettal tavaliselt käivitumise hetkel kõrvale pandud, seega puuduvad tema baidid juba kõrvalolevast vaba ruumi arvust ega tule sellele veel otsa.',
  'disk.tasks': '{n} allalaadimist',
  'disk.unknown': 'See süsteem ei teata vaba ruumi',
  'disk.unknownHint': 'Mitte igalt tuumalt ei saa küsida, kui palju ruumi andmekandjal alles on, ja sellel buildil pole päringut selle jaoks, millel see töötab. Kus vastus puudub, ei hoita midagi tagasi: allalaadimised käivituvad, nagu poleks kettapiirangut seatud. See rida on siin selleks, et saaksid seda eristada kettast, mis on päriselt täis.',
  'disk.missing': 'Veel loomata',
  'disk.missingHint': 'Selle kausta teeb see, kes esimese faili sinna kirjutab, seega teda veel ei ole. Arvud kirjeldavad kausta {path}, lähimat olemasolevat kausta selle kohal, ja see asub andmekandjal, kuhu allalaadimine maanduks.',
  'disk.measured': 'Mõõdetud kaustas {path}',
  'disk.elsewhereHint': 'Kausta ennast ei õnnestunud mõõta, seepärast mõõdeti lähimat kausta selle kohal. Kui mõni haakepunkt üles ei tulnud, võib see olla hoopis teine ketas kui see, mille jaoks allalaadimine mõeldud on. Vaata tee üle, enne kui arvudest midagi järeldad.',
  'disk.sampled': 'Loetud {n} sekundit tagasi',
  'disk.tight': 'Järjekord ei mahu ära',
  'disk.tightHint': 'Sellele kaustale võlgnetakse rohkem, kui andmekandjal vaba on. See rida ise ei peata midagi: tagasi hoitakse ükshaaval, siis kui allalaadimine ette jõuab, allalaadimiste seadete lehel olevate arvude järgi. Allalaadimine, mille suurust keegi ei tea, ei lähe siin üldse arvesse.',
  'disk.truncated': 'Kõik kaustad ei ole siin',
  'disk.truncatedHint': 'Järjekord sihib seadistatutest väljapoole rohkem kaustu, kui neid iga lugemise juures mõõta tasub, seepärast jäid välja need, millele võlgnetakse kõige vähem. Iga kaust, mille sa ise seadistasid, on alati siin.',
  'disk.markLow': 'Siit allpool ei käivitu midagi uut',
  'disk.markStop': 'Siit allpool peatub kõik',
  'disk.limits': 'Sea kettaruumi piirid',
  'disk.stripLabel': 'Ruum sihtkaustades',
  'disk.role.downloads': 'Allalaadimiste kaust',
  'disk.role.category': 'Kategooria kaust',
  'disk.role.work': 'Töökaust',
  'disk.role.task': 'Määratud allalaadimisel endal',

  'settings.volume.title': 'Mahupiir',
  'settings.volume.titleHint': 'Mida see eksemplar on valmis alla laadinud, mõõdetuna sinu seatud piiri vastu, ajavahemiku kaupa. Loetakse suurust, mille hoster valmis saanud allalaadimise kohta nimetas. Mis saab valmis ilma nimetatud suuruseta, loeb nulliks, ja mida torrent üles laadib, ei loe üldse. See on sinu allalaadimiste kokkuvõte, mitte sinu liini mõõtmine: seda, mida su ruuter päriselt liigutas, ei näe siin keegi.',
  'settings.volume.cap': 'Piir ajavahemiku kohta (GB)',
  'settings.volume.capHint': '0 tähendab, et piiri ei ole: loendur jookseb edasi ja midagi ei peeta kunagi tagasi. Gigabaidid on siin kümnendsüsteemis, nii nagu teenusepakkuja oma mahtu nimetab: 500 GB on 500 000 000 000 baiti, mitte 465 GiB. Kettaruumi läved ülalpool sellel lehel on kahendsüsteemi GiB-d, teine ühik teise küsimuse jaoks.',
  'settings.volume.resetDay': 'Loendur alustab uuesti päeval',
  'settings.volume.resetDayHint': 'Kuupäev kuus, mil loendur läheb tagasi nulli, tavaliselt see päev, mil sinu maht uueneb. Kuus, mis on lühem kui valitud päev, alustab ta selle asemel selle kuu viimasel päeval ega libise kunagi järgmisse. Arvestatakse serveri kella järgi, mitte sinu brauseri järgi, sest järjekorda hoiab kinni server.',
  'settings.volume.action': 'Kui piir on täis',
  'settings.volume.actionHint': 'Juba töötavat ülekannet ei katkestata kunagi, ükskõik millise vastuse valid: keset faili peatamine viskab ära baidid, mille oled juba ära kulutanud. „Ainult teata“ ei muuda midagi ja jätab loenduri kogu funktsiooniks. „Ära käivita rohkem allalaadimisi“ laseb töötaval lõpuni jõuda ja hoiab järjekorda kinni, kuni loendur uuesti algab, ja iga ootav rida ütleb seda. „Aeglusta kõike“ hoiab järjekorra käimas allpool oleva kiirusega.',
  'settings.volume.actionReport': 'Ainult teata',
  'settings.volume.actionPause': 'Ära käivita rohkem allalaadimisi',
  'settings.volume.actionThrottle': 'Aeglusta kõike',
  'settings.volume.throttle': 'Kiirus pärast piiri (KiB/s)',
  'settings.volume.throttleHint': 'Piirang, mis kehtib ülejäänud ajavahemiku jooksul. See on ülempiir sinu teiste piirangute kõrval ja mitte kunagi nende asemel: öine aken või vaikne režiim, mis nõuavad vähem, võidavad edasi. 0 tähendaks siin, et piirangut ei ole üldse, ja see on sama mis piirita, seega väikseim mõistlik arv on 1.',
  'settings.volume.noCap': 'Piiri ei ole',
  'settings.volume.used': 'Selles ajavahemikus laaditud',
  'settings.volume.usedOf': '{used} / {cap}',
  'settings.volume.resetsOn': 'Algab uuesti {date}',
  'settings.volume.reached': 'Piir on täis.',
  'volume.title': 'Alla laaditud maht',
  'volume.titleHint': 'Valmis allalaadimised, liidetud päeva ja kuu kaupa, allalaadimiste ajaloost. Ajalool on oma ülempiir ja teda saab käsitsi tühjendada, seega kuud, mis on tagant välja kukkunud, lihtsalt puuduvad siit. Allalaadimine, mille sa uuesti käivitasid, loeb üks kord, sel päeval, mil ta viimati valmis sai. Arvestatakse serveri kalendri järgi, ajavööndis {zone}.',
  'volume.range.days': '30 päeva',
  'volume.range.months': '12 kuud',
  'volume.split.total': 'Kõik',
  'volume.split.host': 'Hosteri kaupa',
