  'volume.other': 'Kõik ülejäänu',
  'volume.empty': 'Selles ajavahemikus ei ole veel midagi valmis saanud.',
  'volume.unsizedHint': 'Neist allalaadimistest {n} said valmis nii, et hoster ei nimetanud kunagi suurust. Nad ei lisa summale midagi, seega on tegelik arv suurem kui siia joonistatud.',
  'volume.trimmedHint': 'Ajalugu on oma piiri peal, seega puudub ka sellelt kõveralt kõik, mis on vanem kui tema vanim kirje. Tõsta sellel lehel ajaloo ülempiiri, kui tahad kaugemale tagasi vaadata.',
  'volume.meter': 'Maht',
  'volume.meterHint': 'Mis on valmis alla laaditud pärast loenduri viimast uuesti algust, mõõdetuna ülempiiri vastu seadete lehel Allalaadimised. Arv muutub, kui allalaadimine lõpeb, mitte selle töötamise ajal. See liidetakse kokku allalaadimiste ajaloost, seega ajaloo tühjendamine paneb ka selle loenduri tagasi nulli.',
