  'settings.diagnostics.fileProblemHint': 'Vaata järele, kas {path} on olemas ja kas konto, mille all see protsess töötab, tohib sinna kirjutada. Unraidis tähendab see enamasti, et kaust kuulub kasutajale root, samal ajal kui konteiner töötab teise kasutaja all. Muu ei ole seisma jäänud: viimased {n} rida on endiselt mälus ja lähevad endiselt diagnostikapaketti.',
  'settings.diagnostics.fileProblemSpace': 'Sellel andmekandjal on veel {free} vaba.',
  'settings.diagnostics.fileProblemSpaceUnknown': 'Kui palju sellel andmekandjal veel ruumi on, seda selles süsteemis välja lugeda ei saa.',
  'settings.diagnostics.fileCurrent': 'Praegune fail',
