  'settings.diagnostics.logSearchHint': 'Lihtne tekst, ilma metamärkideta, suur- ja väiketäht on ühesugused. Otsitakse siia laaditud ridadest, mitte vanematest failidest. Terve faili läbiotsimiseks laadi see alla.',
  'settings.diagnostics.logSource': 'Allikas',
  'settings.diagnostics.logSourceAll': 'Kõik allikad',
  'settings.diagnostics.logSourceOther': 'Ülejäänud read',
  'settings.diagnostics.logSourceHint': 'Millisest rakenduse osast rida tuli, loetuna rea enda algusest. Read, mis ühtki osa ei nimeta, on rubriigis „Ülejäänud read“. Raskusastme järgi ei saa filtreerida: selles rakenduses ei pane ükski rida seda kirja.',
  'settings.diagnostics.logFollow': 'Järgne uutele ridadele',
  'settings.diagnostics.logFollowHint': 'Küsib iga kahe sekundi tagant, mis on pärast eelmist korda juurde tulnud, ja hüppab uusima rea juurde. Välja lülitatuna jääb vaade paigale, nii et sul ei libise lugemise ajal midagi eest ära.',
