  'settings.owner.identityHint': 'Iga fail, mille see eksemplar loob, saab selle omaniku ja need õigused, ja kõik, mille ta käivitab, samuti: yt-dlp, ffmpeg ja kaasas olev JDownloader. Konteineris on isik paigas hetkest, mil konteiner käivitub, ja selle määrab konto, mille all ta käivitati. Sellelt lehelt ei saa selles midagi muuta.',
  'settings.owner.uid': 'Kasutaja',
