  'settings.owner.envHow': 'Kui tahad töötada teise konto all, nimeta see käivituskäsus: --user <uid>:<gid>. Unraidis käib see välja Extra Parameters, ja konteiner tuleb uuesti luua, et see kehtima hakkaks.',
  'settings.owner.desktopNote': 'Töölauarakendus töötab sinu enda konto all. PUID, PGID ja UMASK on konteineri seaded ega tee siin midagi.',
  'settings.owner.noOwners': 'Selles süsteemis ei ole failidel omanikke, seega ei ole midagi võrrelda. See ei ole viga.',
  'settings.owner.checkTitle': 'Kaustade kontroll',
  'settings.owner.checkHint': 'Siin kirjutatakse päriselt igasse kausta üks fail ja üks alamkaust, loetakse tagasi, kellele need kuuluvad ja kes neid veel lugeda tohib, ning eemaldatakse mõlemad jälle. Seda tuleb mõõta, mitte välja arvutada: jagatud kaustal võivad olla omaenda õigusereeglid, ja set-group-id märgiga kaust annab välja teise rühma kui see, mis sellel protsessil on. Kontroll käivitub ise, kui sa muudetud kausta salvestad, ja alati, kui sa nuppu vajutad.',
