  'settings.owner.v.ok': 'Failid maanduvad siia omanikuga {fileOwner} ja õigustega {fileMode}, uued alamkaustad õigustega {subdirMode}, ja kaust ise kuulub omanikule {dirOwner}. Selles ei torka midagi silma.',
  'settings.owner.v.ownerMismatch': 'Failid maanduvad siia omanikuga {fileOwner}, kaust ise kuulub aga omanikule {dirOwner}. Lugemine käib enamasti veel; ümbernimetamine, teisaldamine ja kustutamine teise konto alt mitte, ja kõik, mis eeldab, et kaustale kuulub tema enda sisu, peab neid faile võõraks.',
  'settings.owner.v.groupUnreadable': 'Failid maanduvad siia õigustega {fileMode}, lahti saab neid seega teha ainult {fileOwner}. Mis töötab teise konto all, näeb nimesid ja rohkem midagi.',
  'settings.owner.v.dirUnreadable': 'Uued alamkaustad maanduvad siia õigustega {subdirMode}. Nende sisse ei pääse peale kasutaja {fileOwner} keegi, ükskõik mida failid nende sees lubavad, ja iga allalaadimine maandub just sellises kaustas.',
  'settings.owner.v.notWritable': 'See eksemplar ei saa siia üldse kirjutada: {detail}',
