  'auth.twoFactor.codesTitle': 'Kirjuta need nüüd üles',
  'auth.twoFactor.codesHint': 'See on ainus kord, kui neid näidatakse. Iga kehtib ühe korra rakenduse koodi asemel ja need on ainus, mis su tagasi sisse laseb, kui telefon kaob.',
  'auth.twoFactor.codesAck': 'Olen need üles kirjutanud',
  'auth.twoFactor.recoveryLeft': 'Alles on {n} taastekoodi.',
  'auth.twoFactor.disable': 'Lülita välja',
  'auth.twoFactor.disablePrompt': 'Väljalülitamiseks sisesta kood',
